#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int maxn=atoi(argv[1]);for(int n=4;n<=maxn;n++){vector<pair<int,int>> es;for(int i=0;i<n;i++)for(int j=0;j<i;j++)es.push_back({i,j});long long tested=0,relevant=0;for(unsigned long long mask=0;mask<(1ull<<es.size());mask++){vector<int>a(n);for(int j=0;j<(int)es.size();j++)if(mask>>j&1){auto[u,v]=es[j];a[u]|=1<<v;a[v]|=1<<u;}bool low=false;for(int u=0;u<n;u++)if(__builtin_popcount((unsigned)a[u])<2)low=true;if(low)continue;tested++;vector<int> indep(1<<n),color(1<<n,100),count(n+1);indep[0]=1;color[0]=0;for(int s=1;s<(1<<n);s++){int v=__builtin_ctz((unsigned)s),rest=s^(1<<v);indep[s]=indep[rest]&&!(a[v]&rest);if(indep[s])count[__builtin_popcount((unsigned)s)]++;for(int sub=s;sub;sub=(sub-1)&s)if(indep[sub])color[s]=min(color[s],1+color[s^sub]);}int k=color.back();if(k<4)continue;int conn=n-1;for(int rem=0;rem<(1<<n);rem++){int sz=__builtin_popcount((unsigned)rem);if(sz>=conn)continue;int remain=((1<<n)-1)^rem;if(!remain)continue;int seen=remain&-remain,old=0;while(old!=seen){old=seen;for(int v=0;v<n;v++)if(seen>>v&1)seen|=a[v]&remain;}if(seen!=remain)conn=sz;}for(int l=2;l<k&&l<=conn;l++){relevant++;for(int t=3;t<=n;t++){auto choose=[](int m,int r){long long c=1;if(r>m||r<0)return 0ll;for(int j=1;j<=r;j++)c=c*(m-j+1)/j;return c;};long long bound=choose(n-l,t)+choose(k-l,t); // independent sets in K_l join (K_(k-l) union E_(n-k)): choose independent side plus one clique vertex
bound=choose(n-k,t)+(k-l)*choose(n-k,t-1);if(count[t]>bound){cout<<"COUNTEREXAMPLE n "<<n<<" mask "<<mask<<" k "<<k<<" l "<<l<<" t "<<t<<" count "<<count[t]<<" bound "<<bound<<endl;return 0;}}}}cout<<"n "<<n<<" masks "<<(1ull<<es.size())<<" min_degree_2 "<<tested<<" eligible_parameter_instances "<<relevant<<endl;}}
